UPDATE coupons
SET
    name = #{name},
    total_quantity = #{totalQuantity},
    expires_at = #{expiresAt}
WHERE id = #{id}
  AND status IN ('ACTIVE', 'INACTIVE')
  AND starts_at <= NOW(6)
  AND expires_at > NOW(6)
  AND issued_quantity <= #{totalQuantity}
  AND expires_at <= #{expiresAt}


UPDATE coupons
SET status = #{status}
WHERE id = #{couponId}
